            .baseUrl(BASE_URL)
            .client(okHttpClient)
            .addConverterFactory(GsonConverterFactory.create())
            .build()
    }

    val skyroutezApiService: SkyroutezApiService by lazy {
        retrofit.create(SkyroutezApiService::class.java)
    }
}
