    def _load_staking_abi(self) -> List[Dict]:
        """Load staking contract ABI from file or constant"""
        # In production, this would load from a file or external source
        return [
            {
                "inputs": [{"internalType": "uint256", "name": "amount", "type": "uint256"}],
