    def _load_token_abi(self) -> List[Dict]:
        """Load token contract ABI from file or constant"""
        return [
            {
                "inputs": [{"internalType": "address", "name": "spender", "type": "address"},
                          {"internalType": "uint256", "name": "amount", "type": "uint256"}],
